package org.novasos.healthysv2.pharmacy;
import static org.novasos.healthysv2.pharmacy.PharmacyValues.*;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="prescription_item",schema="pharmacy") class PrescriptionItem{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="prescription_id",nullable=false)private Prescription prescription;@Column(name="medication_catalog_id",nullable=false)private UUID medicationId;@Column(length=100)private String dosage;@Column(length=100)private String frequency;@Column(length=100)private String route;@Column(length=100)private String duration;@Column(precision=12,scale=3)private BigDecimal quantity;@Column(columnDefinition="text")private String instructions;protected PrescriptionItem(){}static PrescriptionItem create(Prescription p,UUID medication,String dosage,String frequency,String route,String duration,BigDecimal quantity,String instructions){if(quantity==null||quantity.signum()<=0)throw new IllegalArgumentException("Quantity required");var x=new PrescriptionItem();x.id=UUID.randomUUID();x.prescription=p;x.medicationId=Objects.requireNonNull(medication);x.dosage=required(dosage);x.frequency=required(frequency);x.route=required(route).toUpperCase();x.duration=required(duration);x.quantity=quantity;x.instructions=optional(instructions);return x;}UUID getId(){return id;}UUID getMedicationId(){return medicationId;}String getDosage(){return dosage;}String getFrequency(){return frequency;}String getRoute(){return route;}String getDuration(){return duration;}BigDecimal getQuantity(){return quantity;}String getInstructions(){return instructions;}}
@Entity @Table(name="dispense",schema="pharmacy") class Dispense{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="prescription_id",nullable=false)private Prescription prescription;@Column(name="dispense_number",nullable=false,unique=true,length=50)private String number;@Column(name="pharmacy_organization_id",nullable=false)private UUID pharmacyOrganizationId;@Column(name="pharmacist_id")private UUID pharmacistId;@Column(name="dispensed_at",nullable=false)private Instant dispensedAt;@Column(nullable=false,length=30)private String status;@OneToMany(mappedBy="dispense",cascade=CascadeType.ALL,orphanRemoval=true)private List<DispenseItem>items=new ArrayList<>();protected Dispense(){}static Dispense create(Prescription p,UUID pharmacy,UUID pharmacist){var x=new Dispense();x.id=UUID.randomUUID();x.prescription=p;x.number="DSP-"+x.id.toString().replace("-","").substring(0,20).toUpperCase();x.pharmacyOrganizationId=Objects.requireNonNull(pharmacy);x.pharmacistId=Objects.requireNonNull(pharmacist);x.dispensedAt=Instant.now();x.status="COMPLETED";return x;}void addItem(PrescriptionItem item,BigDecimal quantity,String batch){items.add(DispenseItem.create(this,item,quantity,batch));}UUID getId(){return id;}String getNumber(){return number;}UUID getPharmacyOrganizationId(){return pharmacyOrganizationId;}UUID getPharmacistId(){return pharmacistId;}Instant getDispensedAt(){return dispensedAt;}String getStatus(){return status;}List<DispenseItem>getItems(){return items;}}
@Entity @Table(name="dispense_item",schema="pharmacy") class DispenseItem{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="dispense_id",nullable=false)private Dispense dispense;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="prescription_item_id",nullable=false)private PrescriptionItem prescriptionItem;@Column(name="quantity_dispensed",nullable=false,precision=12,scale=3)private BigDecimal quantity;@Column(name="batch_number",length=100)private String batch;protected DispenseItem(){}static DispenseItem create(Dispense d,PrescriptionItem item,BigDecimal quantity,String batch){var x=new DispenseItem();x.id=UUID.randomUUID();x.dispense=d;x.prescriptionItem=item;x.quantity=quantity;x.batch=required(batch);return x;}UUID getId(){return id;}UUID getPrescriptionItemId(){return prescriptionItem.getId();}BigDecimal getQuantity(){return quantity;}String getBatch(){return batch;}}
@Entity @Table(name="medication_stock",schema="pharmacy",uniqueConstraints=@UniqueConstraint(columnNames={"organization_id","medication_catalog_id","batch_number"})) class MedicationStock{@Id private UUID id;@Column(name="organization_id",nullable=false)private UUID organizationId;@Column(name="medication_catalog_id",nullable=false)private UUID medicationId;@Column(name="batch_number",length=100)private String batch;@Column(nullable=false,precision=14,scale=3)private BigDecimal quantity;@Column(name="expiration_date")private LocalDate expirationDate;protected MedicationStock(){}static MedicationStock create(UUID organization,UUID medication,String batch,BigDecimal quantity,LocalDate expiration){if(quantity==null||quantity.signum()<=0)throw new IllegalArgumentException("Positive quantity required");var x=new MedicationStock();x.id=UUID.randomUUID();x.organizationId=Objects.requireNonNull(organization);x.medicationId=Objects.requireNonNull(medication);x.batch=required(batch);x.quantity=quantity;x.expirationDate=expiration;return x;}void replenish(BigDecimal amount,LocalDate expiration){if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("Positive quantity required");quantity=quantity.add(amount);if(expiration!=null)expirationDate=expiration;}void consume(BigDecimal amount){if(expired()||amount==null||amount.signum()<=0||quantity.compareTo(amount)<0)throw new IllegalStateException("Insufficient stock");quantity=quantity.subtract(amount);}boolean expired(){return expirationDate!=null&&expirationDate.isBefore(LocalDate.now());}UUID getId(){return id;}UUID getOrganizationId(){return organizationId;}UUID getMedicationId(){return medicationId;}String getBatch(){return batch;}BigDecimal getQuantity(){return quantity;}LocalDate getExpirationDate(){return expirationDate;}}
final class PharmacyValues{private PharmacyValues(){}static String required(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("Required value");return v.trim();}static String optional(String v){return v==null||v.isBlank()?null:v.trim();}}
